import { Component, EventEmitter, Event, Prop, State, h, Listen, Method, Watch } from '@stencil/core';

@Component({
  tag: 'std-single-select',
  styleUrl: 'std-single-select.css',
  shadow: true
})
export class StdSingleSelect {
  @Prop({
    mutable: true
  })
  items: any[] = [];
  @Prop() displayProp: string;
  @Prop() valueProp: string;
  @Prop() altDisplayProp: string;
  @Prop() placeholder: string = 'Select an option';
  @Prop() disabled = false;
  @Prop() label: string;
  @Prop() labelClasses: string;
  @Prop() readonly: boolean;
  @Prop() classes: string;
  @Prop() helperText: string;
  @Prop() status = 'default';
  @Prop() disabledAsReadonly = false;
  @Prop() deselected: boolean = false;
  @Prop() searchable: boolean = false;
  @Prop() criteria: string;
  @Prop() altDisplayFn: Function;
  @Prop() displayShow: string;
  @Prop({ mutable: true, reflect: true }) value: any;

  @Event({
    bubbles: false
  })
  changeEvent: EventEmitter<any>;
  @Event({
    bubbles: false
  })
  blurEvent: EventEmitter;

  @Prop({ mutable: true }) selectedItem: any | null = null;
  @State() isOpen = false;
  @State() searchValue: string = '';
  @State() filteredItems: any[] = [];
  @State() valueRaw: any;

  selectElement: HTMLButtonElement;
  menuElement: HTMLDivElement;

  componentWillLoad() {
    this.filteredItems = this.items;
  }

  @Watch('value')
  valueChanged(newValue: string) {
    this.setSelectedValue(newValue);
  }

  @Watch('items')
  setFilteredItems() {
    this.filteredItems = this.items;
    this.setSelectedValue(this.valueRaw);
  }

  @Method()
  async setSelectedValue(selectedItem: any) {
    this.valueRaw = selectedItem;
    if (this.selectedItem === selectedItem) {
      if(this.deselected) {
        this.selectedItem = null;
        this.changeEvent.emit(null);
        return;
      }else {
        return;
      }
    }
    let valueToEmit: any;
    if (this.valueProp) {
      this.selectedItem = typeof selectedItem === 'object' ? selectedItem : this.filteredItems.find(item => item[this.valueProp] === selectedItem);
      valueToEmit = this.selectedItem ? this.selectedItem[this.valueProp] : selectedItem;
    } else {
      this.selectedItem = selectedItem;
      valueToEmit = selectedItem;
    }
    this.changeEvent.emit(valueToEmit);
  }

  onSelectBlur() {
    this.blurEvent.emit();
  }

  private toggleDropdown() {
    if (!this.readonly && !this.disabled) {
      this.isOpen = !this.isOpen;
    }
  }

  private displayTextShow(item: any): string {
    const displayText = item[this.displayShow];
    if (!displayText) {
      throw new Error(`std-single-select | Property '${this.displayShow}' does not exist on : ${JSON.stringify(this.items)}`);
    }
    return String(displayText);
  }

  private displayText(item: any): string {
    const displayText = item[this.displayProp];
    if (!displayText) {
      throw new Error(`std-single-select | Property '${this.displayProp}' does not exist on : ${JSON.stringify(this.items)}`);
    }
    return String(displayText);
  }

  private altDisplayText(item: any): string {
    const displayText = this.altDisplayFn ? this.altDisplayFn(item) : item[this.altDisplayProp];
    if (!displayText) {
      throw new Error(`std-single-select | Property '${this.altDisplayProp}' does not exist on : ${JSON.stringify(this.items)}`);
    }
    return String(displayText);
  }

  private isDisabledAsReadonly(): boolean {
    return this.disabledAsReadonly && this.disabled && !!this.selectedItem;
  }

  private handleInputChange(event: Event) {
    const input = event.target as HTMLInputElement;
    this.searchValue = input.value;
  }

  private sanitizer(value: string) {
    if (typeof value !== 'string') return '';
    return String(value ?? '')
      .toLowerCase()
      .trim();
  }

  private spliterLabel(indicator: string, object: any) {
    let valueFiler = ``;
    indicator.split('.').map(e => (valueFiler += object[e]));
    return valueFiler;
  }

  private filterObject(object: any) {
    const spliter = Object.keys(this.items[0]).join('.');
    return this.spliterLabel(this.criteria || spliter, object);
  }

  get statusClasses() {
    return {
      default: 'border-border-default ',
      success: 'border-border-default hover:border-dark focus:border-alternative focus:ring-alternative',
      error: 'border-error focus:border-error focus:ring-error'
    }[this.status];
  }

  get selectClasses() {
    return [
      'relative !h-[46px] css-select w-full bg-white border rounded-lg',
      this.readonly || this.disabled ? 'border-transparent pointer-events-none' : this.statusClasses,
      this.classes
    ]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');
  }

  get labelClass() {
    return [this.labelClasses, this.disabled && !this.isDisabledAsReadonly() ? 'opacity-20 cursor-not-allowed' : ''].join(' ').trim();
  }

  get buttonClasses() {
    return [
      'inline-flex w-full items-center justify-between p-[6px] px-[11px] text-base rounded-lg',
      this.readonly || this.disabled ? ' bg-dark/[0.06]  cursor-not-allowed' : '',
      this.disabled && !this.isDisabledAsReadonly() ? 'text-dark/[0.23]' : '',
      !this.selectedItem ? 'text-soft font-normal' : ''
    ]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');
  }

  get iconClasses() {
    return [
      'icon-chevron-down text-2xl',
      !this.readonly && !this.disabled ? 'text-alternative' : '',
      (this.readonly || this.isDisabledAsReadonly()) && 'text-soft',
      this.disabled && !this.isDisabledAsReadonly() && 'text-dark/[0.23]'
    ]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');
  }

  @Listen('click', { target: 'document' })
  checkForClickOutside(ev: PointerEvent): void {
    const path = ev.composedPath();
    const validateInput = this.menuElement && !path.includes(this.menuElement);
    const validateSingle = !this.menuElement && !path.includes(this.selectElement);
    if (this.isOpen && (validateInput || validateSingle)) {
      this.onSelectBlur();
      this.isOpen = false;
      return;
    }
  }

  @Watch('searchValue')
  watchPropHandler(newValue: string) {
    this.filteredItems = this.items.filter(e => {
      return this.sanitizer(this.filterObject(e)).includes(this.sanitizer(newValue));
    });
  }

  render() {
    return (
      <div class="flex flex-col gap-1 w-full">
        {this.label && <p class={this.labelClass}>{this.label}</p>}
        <div class={this.selectClasses}>
          <button ref={el => (this.selectElement = el)} type="button" class={this.buttonClasses} onClick={() => this.toggleDropdown()}>
            {this.displayShow ? (
              <span class="text-ellipsis whitespace-nowrap overflow-hidden">{(this.selectedItem && this.displayTextShow(this.selectedItem)) || this.placeholder}</span>
            ): (
              <span class="text-ellipsis whitespace-nowrap overflow-hidden">{(this.selectedItem && this.displayText(this.selectedItem)) || this.placeholder}</span>

            )}
            <i class={this.iconClasses} />
          </button>
          {this.isOpen && (
            <div class="flex-col left-[-1px] w-[calc(100%+2px)] px-4 bg-white absolute top-[48px] z-10 shadow-modal rounded-md">
              {this.searchable && (
                <div class="py-4" ref={el => (this.menuElement = el)}>
                  <div class="flex flex-col gap-1">
                    <div class="relative">
                      <i class="absolute top-3 left-3 text-2xl leading-none icon-search" />
                      <input
                        class="h-12 rounded-lg p-3 placeholder:text-soft pl-12 w-full border-border-default hover:border-dark focus:border-alternative focus:ring-alternative"
                        type="search"
                        value={this.searchValue}
                        placeholder="Buscar"
                        autocomplete="off"
                        onInput={e => this.handleInputChange(e)}
                      />
                    </div>
                  </div>
                </div>
              )}
              <ul class="w-full flex flex-col gap-1 py-1 max-h-[216px] overflow-y-auto">
                {this.filteredItems.map(item => (
                  <li
                    class={`flex justify-between items-center gap-2 rounded hover:bg-alternative-light p-3 transition-all duration-300 cursor-pointer ${
                      this.selectedItem === item ? 'bg-alternative-light font-bold' : ''
                    }`}
                    onClick={() => this.setSelectedValue(item)}>
                    {this.displayProp && !this.altDisplayProp && !this.altDisplayFn && <span class="text-base text-dark">{this.displayText(item)}</span>}
                    {(this.altDisplayProp || this.altDisplayFn) && (
                      <div class="flex flex-col">
                        <span class="text-lg text-dark font-headline font-bold">{this.displayText(item)}</span>
                        <span class="text-sm text-dark">{this.altDisplayText(item)}</span>
                      </div>
                    )}
                    {this.selectedItem === item && <i class="shrink-0 text-2xl leading-none text-alternative icon-checkmark" />}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
        {this.helperText && <std-helpertext label={this.helperText} status={this.status} disabled={this.disabled && !this.isDisabledAsReadonly()} />}
      </div>
    );
  }
}
